{"path":"src/counter.rs","classification":"source_code","content":"use std::sync::{Arc, Mutex};

pub struct Counter {
    value: Arc<Mutex<u64>>,
}

impl Counter {
    pub fn new(initial: u64) -> Self {
        Self { value: Arc::new(Mutex::new(initial)) }
    }

    pub fn increment(&self) -> u64 {
        let mut value = self.value.lock().expect("counter lock poisoned");
        *value += 1;
        *value
    }

    pub fn current(&self) -> u64 {
        *self.value.lock().expect("counter lock poisoned")
    }
}
